static lstr L2423 = {-1, 1014, "// std/coroutine: Co.resume runs a generator or a coroutine to its next yield.\012//\012// The compiler turns `Co.resume(mutable g)` into resumeGenerator and\012// `Co.resume(mutable g, input)` into resumeCoroutine, by argument count.\012\012import * as Internal from \"std/internal/coroutine\"\012\012export enum Step<Out> derives Show, Equatable {\012  Yielded(value: Out)\012  Done\012  Panicked(message: string)\012}\012\012export function resumeGenerator<T, effect E>(mutable g: Generator<T> uses E): Step<T> uses E, alloc {\012  return stepOf(Internal.next(mutable g))\012}\012\012export function resumeCoroutine<In, Out, effect E>(mutable g: Coroutine<In, Out> uses E, input: In): Step<Out> uses E, alloc {\012  return stepOf(Internal.resume(mutable g, input))\012}\012\012// stepOf reads the outcome of one resume: a value, the end, or a panic.\012function stepOf<T>(next: Option<T>): Step<T> uses alloc {\012  if (next is Some(value)) {\012    return Step.Yielded(value)\012  }\012  if (Internal.panicked()) {\012    return Step.Panicked(Internal.panicMessage())\012  }\012  return Step.Done\012}\012"};
static lstr L2424 = {-1, 10, "std/option"};
static lstr L2425 = {-1, 1084, "// std/option: helpers over the prelude Option.\012\012export function map<T, U, effect E>(option: Option<T>, f: (value: T) => U uses E): Option<U> uses alloc, E {\012  return match (option) {\012    Some(value) => Some(f(value))\012    None => None\012  }\012}\012\012export function andThen<T, U, effect E>(option: Option<T>, f: (value: T) => Option<U> uses E): Option<U> uses E {\012  return match (option) {\012    Some(value) => f(value)\012    None => None\012  }\012}\012\012export function withDefault<T>(option: Option<T>, fallback: T): T {\012  return match (option) {\012    Some(value) => value\012    None => fallback\012  }\012}\012\012export function orElse<T, effect E>(option: Option<T>, f: () => Option<T> uses E): Option<T> uses E {\012  return match (option) {\012    Some(_) => option\012    None => f()\012  }\012}\012\012export function isSome<T>(option: Option<T>): bool {\012  return option is Some(_)\012}\012\012export function isNone<T>(option: Option<T>): bool {\012  return option is None\012}\012\012export function okOr<T, F>(option: Option<T>, error: F): Result<T, F> uses alloc {\012  return match (option) {\012    Some(value) => Ok(value)\012    None => Err(error)\012  }\012}\012"};
